		&XMLWhenFilterLoading;
		&XMLWhenFilterClosing;
		
		
			
				
select @ngay_ct1 as ngay_ct1, @ngay_ct2 as ngay_ct2
exec zrpt_loadcont @ngay_ct1, @ngay_ct2, @ma_kh, @stt_rec_ct, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter;
			&ScriptQueryFilterString; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	f._looking = f.getItem('so_ct')._controlBehavior;
	f._looking.add_loading(on$&Identity;Filter$Before$Loading);
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('ngay_ct1').value, true], ['%s2', f.getItem('ngay_ct2').value, true]]];
			g._queryFilterString = getQueryFilterString(f, 'ngay_ct1, ngay_ct2');
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function on$&Identity;Filter$Before$Loading(sender, e) {
	var f = sender._element.parentForm;
	if (!f.validFields('ngay_ct1') || !f.validFields('ngay_ct2')) e.type.cancelEvent = true;
	else {
		var d1 = f.getItemValue('ngay_ct1'), d2 = f.getItemValue('ngay_ct2'), u = f.getItemValue('ma_dvcs'), cusID = f.getItemValue('ma_kh')

		a = [
			{Name: 'ngay_ct1', Type: 'DateTime', Value: d1}, 
			{Name: 'ngay_ct2', Type: 'DateTime', Value: d2},
			{Name: 'ma_kh', Type: 'String', Value: cusID},
			{Name: 'ma_dvcs', Type: 'String', Value: u}
		];
		sender.set_memvars(a);
	}
}


		
	

	&OutlineCss;
